-- Local M04 publication state for owner-managed offers. This does not expose
-- spaces in a general/public catalog; discovery is connected in its own cut.
ALTER TABLE public.espacio
    DROP CONSTRAINT IF EXISTS espacio_estado_check,
    ADD CONSTRAINT espacio_estado_local_publication_ck
        CHECK (estado IN ('borrador','activa','oculta'));

CREATE TABLE public.espacio_publicacion_historial_local (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    espacio_id uuid NOT NULL REFERENCES public.espacio(id) ON DELETE RESTRICT,
    actor_id uuid NOT NULL REFERENCES public.usuario(id) ON DELETE RESTRICT,
    estado_anterior text NOT NULL CHECK (estado_anterior IN ('borrador','activa','oculta')),
    estado_nuevo text NOT NULL CHECK (estado_nuevo IN ('activa','oculta')),
    ocurrida_en timestamptz NOT NULL,
    correlacion_id text NOT NULL CHECK (length(btrim(correlacion_id)) BETWEEN 1 AND 120),
    CONSTRAINT espacio_publicacion_transicion_ck CHECK (
        (estado_anterior IN ('borrador','oculta') AND estado_nuevo='activa')
        OR (estado_anterior='activa' AND estado_nuevo='oculta')
    )
);
CREATE INDEX espacio_publicacion_historial_order_idx
    ON public.espacio_publicacion_historial_local(espacio_id,id);

CREATE OR REPLACE FUNCTION public.prevent_local_publication_history_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'local publication history is append-only' USING ERRCODE='55000';
END;
$$;
CREATE TRIGGER espacio_publicacion_historial_append_only
    BEFORE UPDATE OR DELETE ON public.espacio_publicacion_historial_local
    FOR EACH ROW EXECUTE FUNCTION public.prevent_local_publication_history_mutation();

-- LOCAL-COMM-01: synthetic reviews/reports and transactional Mailpit notice intents.
-- These records have local prototype retention only; the periods are not legal claims.

CREATE TABLE public.resena_ensayo_local (
    id uuid PRIMARY KEY,
    reserva_id uuid NOT NULL REFERENCES public.reserva_ensayo_local(id) ON DELETE RESTRICT,
    espacio_id uuid NOT NULL REFERENCES public.espacio(id) ON DELETE RESTRICT,
    autor_id uuid REFERENCES public.usuario(id) ON DELETE RESTRICT,
    destinatario_tipo text NOT NULL CHECK (destinatario_tipo IN ('espacio','arrendatario')),
    destinatario_id uuid REFERENCES public.usuario(id) ON DELETE RESTRICT,
    puntuacion smallint NOT NULL CHECK (puntuacion BETWEEN 1 AND 5),
    comentario text NOT NULL DEFAULT '',
    estado text NOT NULL DEFAULT 'publicada' CHECK (estado IN ('publicada','reportada','oculta')),
    creada_en timestamptz NOT NULL,
    retirar_en timestamptz NOT NULL,
    huella_solicitud bytea NOT NULL CHECK (octet_length(huella_solicitud)=32),
    clave_idempotencia text NOT NULL CHECK (length(btrim(clave_idempotencia)) BETWEEN 8 AND 200),
    UNIQUE (reserva_id,autor_id),
    CHECK ((destinatario_tipo='espacio' AND destinatario_id IS NULL) OR
           (destinatario_tipo='arrendatario' AND destinatario_id IS NOT NULL)),
    CHECK (retirar_en = creada_en + interval '24 months')
);
CREATE INDEX resena_espacio_publica_idx ON public.resena_ensayo_local(espacio_id,creada_en DESC,id)
    WHERE estado IN ('publicada','reportada');
CREATE INDEX resena_arrendatario_idx ON public.resena_ensayo_local(destinatario_id,creada_en DESC,id)
    WHERE destinatario_tipo='arrendatario' AND estado IN ('publicada','reportada');
CREATE INDEX resena_retirar_idx ON public.resena_ensayo_local(retirar_en,id);

CREATE TABLE public.reporte_resena_ensayo_local (
    id uuid PRIMARY KEY,
    resena_id uuid NOT NULL UNIQUE REFERENCES public.resena_ensayo_local(id) ON DELETE RESTRICT,
    espacio_id uuid NOT NULL REFERENCES public.espacio(id) ON DELETE RESTRICT,
    anfitrion_id uuid REFERENCES public.usuario(id) ON DELETE RESTRICT,
    motivo_codigo text NOT NULL CHECK (motivo_codigo IN ('insultos_acoso','datos_personales','spam','ajeno_experiencia')),
    estado text NOT NULL CHECK (estado IN ('pendiente','desestimada','oculta')),
    creada_en timestamptz NOT NULL,
    resolver_en timestamptz,
    resuelta_por uuid REFERENCES public.usuario(id) ON DELETE RESTRICT,
    motivo_resolucion_codigo text CHECK (motivo_resolucion_codigo IN ('sin_infraccion','contenido_inadecuado','duplicado','error_registro')),
    retirar_en timestamptz,
    clave_idempotencia text NOT NULL CHECK (length(btrim(clave_idempotencia)) BETWEEN 8 AND 200),
    huella_solicitud bytea NOT NULL CHECK (octet_length(huella_solicitud)=32),
    CHECK ((estado='pendiente' AND resolver_en IS NULL AND resuelta_por IS NULL AND motivo_resolucion_codigo IS NULL AND retirar_en IS NULL)
        OR (estado IN ('desestimada','oculta') AND resolver_en IS NOT NULL AND resuelta_por IS NOT NULL AND motivo_resolucion_codigo IS NOT NULL AND retirar_en=resolver_en + interval '24 months'))
);
CREATE INDEX reporte_resena_retencion_idx ON public.reporte_resena_ensayo_local(retirar_en,id) WHERE retirar_en IS NOT NULL;
CREATE TABLE public.reporte_resena_historial_local (
    secuencia bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    reporte_id uuid NOT NULL REFERENCES public.reporte_resena_ensayo_local(id) ON DELETE RESTRICT,
    estado_anterior text CHECK (estado_anterior IN ('pendiente','desestimada','oculta')),
    estado_nuevo text NOT NULL CHECK (estado_nuevo IN ('pendiente','desestimada','oculta')),
    actor_id uuid REFERENCES public.usuario(id) ON DELETE RESTRICT,
    motivo_codigo text NOT NULL,
    ocurrida_en timestamptz NOT NULL
);
CREATE INDEX reporte_resena_historial_idx ON public.reporte_resena_historial_local(reporte_id,secuencia);

-- Per-recipient durable intent. No recipient address, message body, SMTP response or secrets are persisted.
CREATE TABLE public.aviso_local (
    id uuid PRIMARY KEY,
    tipo_evento text NOT NULL CHECK (tipo_evento IN ('checkin_registrado','resena_reportada','reclamo_abierto','reserva_cancelada')),
    agregado_tipo text NOT NULL CHECK (agregado_tipo IN ('reserva','reporte_resena')),
    agregado_id uuid NOT NULL,
    destinatario_id uuid NOT NULL REFERENCES public.usuario(id) ON DELETE RESTRICT,
    clave_deduplicacion text NOT NULL UNIQUE,
    estado text NOT NULL DEFAULT 'pendiente' CHECK (estado IN ('pendiente','procesando','entregada','fallo_terminal','cancelada')),
    ciclo integer NOT NULL DEFAULT 1 CHECK (ciclo > 0),
    intentos_total integer NOT NULL DEFAULT 0 CHECK (intentos_total >= 0),
    intentos_ciclo integer NOT NULL DEFAULT 0 CHECK (intentos_ciclo BETWEEN 0 AND 8),
    creada_en timestamptz NOT NULL,
    proximo_intento_en timestamptz NOT NULL,
    lease_hasta timestamptz,
    entregada_en timestamptz,
    fallo_terminal_en timestamptz,
    cancelada_en timestamptz,
    codigo_error text,
    retirar_en timestamptz,
    CHECK ((estado='entregada' AND entregada_en IS NOT NULL AND retirar_en=entregada_en + interval '30 days')
        OR (estado='fallo_terminal' AND fallo_terminal_en IS NOT NULL AND retirar_en=fallo_terminal_en + interval '30 days')
        OR (estado='cancelada' AND cancelada_en IS NOT NULL AND retirar_en=cancelada_en + interval '30 days')
        OR (estado IN ('pendiente','procesando') AND retirar_en IS NULL))
);
CREATE INDEX aviso_local_due_idx ON public.aviso_local(estado,proximo_intento_en,id);
CREATE INDEX aviso_local_recipient_idx ON public.aviso_local(destinatario_id,creada_en DESC,id);
CREATE TABLE public.aviso_local_ciclo (
    aviso_id uuid NOT NULL REFERENCES public.aviso_local(id) ON DELETE RESTRICT,
    ciclo integer NOT NULL,
    estado text NOT NULL CHECK (estado IN ('pendiente','entregada','fallo_terminal','cancelada')),
    iniciada_en timestamptz NOT NULL,
    finalizada_en timestamptz,
    intentos integer NOT NULL DEFAULT 0 CHECK (intentos BETWEEN 0 AND 8),
    codigo_resultado text,
    actor_reapertura_id uuid REFERENCES public.usuario(id) ON DELETE RESTRICT,
    motivo_reapertura_codigo text CHECK (motivo_reapertura_codigo IN ('smtp_restaurado','reintento_operativo')),
    correlacion_id text,
    clave_idempotencia text,
    PRIMARY KEY(aviso_id,ciclo), UNIQUE(aviso_id,clave_idempotencia),
    CHECK ((estado='pendiente')=(finalizada_en IS NULL))
);
CREATE TABLE public.aviso_local_recuperacion_auditoria (
    id uuid PRIMARY KEY,
    aviso_id uuid NOT NULL,
    actor_id uuid NOT NULL REFERENCES public.usuario(id) ON DELETE RESTRICT,
    motivo_codigo text NOT NULL CHECK (motivo_codigo IN ('smtp_restaurado','reintento_operativo')),
    ocurrida_en timestamptz NOT NULL,
    correlacion_id text NOT NULL,
    clave_idempotencia text NOT NULL,
    retirar_en timestamptz NOT NULL,
    UNIQUE(aviso_id,clave_idempotencia),
    CHECK (retirar_en=ocurrida_en + interval '5 years')
);

CREATE FUNCTION public.enqueue_local_notice(p_type text,p_aggregate_type text,p_aggregate uuid,p_recipient uuid,p_key text,p_at timestamptz)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE notice_id uuid := gen_random_uuid();
BEGIN
    IF p_recipient IS NULL THEN RETURN; END IF;
    INSERT INTO public.aviso_local(id,tipo_evento,agregado_tipo,agregado_id,destinatario_id,clave_deduplicacion,creada_en,proximo_intento_en)
    VALUES(notice_id,p_type,p_aggregate_type,p_aggregate,p_recipient,p_key,p_at,p_at)
    ON CONFLICT(clave_deduplicacion) DO NOTHING;
    IF EXISTS (SELECT 1 FROM public.aviso_local WHERE clave_deduplicacion=p_key) THEN
      INSERT INTO public.aviso_local_ciclo(aviso_id,ciclo,estado,iniciada_en)
      SELECT id,ciclo,'pendiente',creada_en FROM public.aviso_local WHERE clave_deduplicacion=p_key
      ON CONFLICT DO NOTHING;
    END IF;
END $$;

CREATE FUNCTION public.enqueue_local_checkin_notice() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE host uuid; BEGIN
  IF NEW.tipo='checkin' THEN
    SELECT anfitrion_id INTO host FROM public.reserva_ensayo_local WHERE id=NEW.reserva_id;
    PERFORM public.enqueue_local_notice('checkin_registrado','reserva',NEW.reserva_id,host,'checkin:'||NEW.id::text,NEW.ocurrio_en);
  END IF; RETURN NEW;
END $$;
CREATE TRIGGER local_checkin_notice_trg AFTER INSERT ON public.operacion_arriendo_ensayo_local FOR EACH ROW EXECUTE FUNCTION public.enqueue_local_checkin_notice();

CREATE FUNCTION public.enqueue_local_claim_notice() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM public.enqueue_local_notice('reclamo_abierto','reserva',NEW.reserva_id,NEW.arrendatario_id,'claim:'||NEW.id::text,NEW.abierto_en);
  RETURN NEW;
END $$;
CREATE TRIGGER local_claim_notice_trg AFTER INSERT ON public.reclamo_dano_ensayo_local FOR EACH ROW EXECUTE FUNCTION public.enqueue_local_claim_notice();

CREATE FUNCTION public.enqueue_local_cancel_notice() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.estado NOT IN ('cancelada_por_pago','rechazada_arrendador','vencida_pago','vencida_host','cancelada_arrendatario','cancelada_por_firma') AND NEW.estado IN ('cancelada_por_pago','rechazada_arrendador','vencida_pago','vencida_host','cancelada_arrendatario','cancelada_por_firma') THEN
    PERFORM public.enqueue_local_notice('reserva_cancelada','reserva',NEW.id,NEW.anfitrion_id,'cancel:'||NEW.id::text||':'||NEW.estado||':host',NEW.actualizada_en);
    PERFORM public.enqueue_local_notice('reserva_cancelada','reserva',NEW.id,NEW.arrendatario_id,'cancel:'||NEW.id::text||':'||NEW.estado||':renter',NEW.actualizada_en);
  END IF; RETURN NEW;
END $$;
CREATE TRIGGER local_cancel_notice_trg AFTER UPDATE OF estado ON public.reserva_ensayo_local FOR EACH ROW EXECUTE FUNCTION public.enqueue_local_cancel_notice();

CREATE FUNCTION public.enqueue_local_review_report_notice() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE admin record; BEGIN
  FOR admin IN SELECT ru.usuario_id FROM public.rol_usuario ru JOIN public.usuario u ON u.id=ru.usuario_id WHERE ru.rol='administrador' AND u.estado='activo' LOOP
    PERFORM public.enqueue_local_notice('resena_reportada','reporte_resena',NEW.id,admin.usuario_id,'review-report:'||NEW.id::text||':'||admin.usuario_id::text,NEW.creada_en);
  END LOOP; RETURN NEW;
END $$;
CREATE TRIGGER local_review_report_notice_trg AFTER INSERT ON public.reporte_resena_ensayo_local FOR EACH ROW EXECUTE FUNCTION public.enqueue_local_review_report_notice();

ALTER TABLE public.evento_auditoria_local DROP CONSTRAINT evento_auditoria_idempotencia_ck;
ALTER TABLE public.evento_auditoria_local ADD CONSTRAINT evento_auditoria_idempotencia_ck CHECK (
    clave_idempotencia IS NULL OR (
        length(btrim(clave_idempotencia)) BETWEEN 1 AND 200
        AND ((accion IN ('privacy.suppression.review','privacy.suppression.execute') AND recurso_tipo='solicitud_titular')
          OR (accion='identity.credential_notice.reopen' AND recurso_tipo='outbox_evento')
          OR (accion='reputation.review.moderate' AND recurso_tipo='reporte_resena'))
    )
);

-- Bounded retention worker API; application role gets EXECUTE, not unrestricted deletes.
CREATE FUNCTION public.purge_expired_local_communication(p_at timestamptz,p_limit integer)
RETURNS TABLE(reviews_purged bigint,reports_purged bigint,notices_purged bigint)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE ids uuid[];
BEGIN
  IF p_limit<1 OR p_limit>500 THEN RAISE EXCEPTION 'invalid batch'; END IF;
  SELECT array_agg(id) INTO ids FROM (
    SELECT r.id FROM public.reporte_resena_ensayo_local r
    WHERE r.estado IN ('desestimada','oculta') AND r.retirar_en<=p_at
    ORDER BY r.retirar_en,r.id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ) due;
  IF cardinality(ids)>0 THEN
    DELETE FROM public.reporte_resena_historial_local WHERE reporte_id=ANY(ids);
    DELETE FROM public.reporte_resena_ensayo_local WHERE id=ANY(ids);
    GET DIAGNOSTICS reports_purged = ROW_COUNT;
  ELSE reports_purged := 0; END IF;

  SELECT array_agg(id) INTO ids FROM (
    SELECT r.id FROM public.resena_ensayo_local r
    WHERE r.retirar_en<=p_at AND NOT EXISTS(SELECT 1 FROM public.reporte_resena_ensayo_local q WHERE q.resena_id=r.id)
    ORDER BY r.retirar_en,r.id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ) due;
  IF cardinality(ids)>0 THEN
    DELETE FROM public.resena_ensayo_local WHERE id=ANY(ids);
    GET DIAGNOSTICS reviews_purged = ROW_COUNT;
  ELSE reviews_purged := 0; END IF;

  SELECT array_agg(id) INTO ids FROM (
    SELECT a.id FROM public.aviso_local a
    WHERE a.retirar_en<=p_at AND a.estado IN ('entregada','fallo_terminal','cancelada') AND a.lease_hasta IS NULL
    ORDER BY a.retirar_en,a.id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ) due;
  IF cardinality(ids)>0 THEN
    DELETE FROM public.aviso_local_ciclo WHERE aviso_id=ANY(ids);
    DELETE FROM public.aviso_local WHERE id=ANY(ids);
    GET DIAGNOSTICS notices_purged = ROW_COUNT;
  ELSE notices_purged := 0; END IF;
  DELETE FROM public.aviso_local_recuperacion_auditoria
  WHERE id IN (SELECT id FROM public.aviso_local_recuperacion_auditoria ORDER BY retirar_en,id LIMIT p_limit)
    AND retirar_en<=p_at;
  RETURN NEXT;
END $$;
REVOKE ALL ON FUNCTION public.purge_expired_local_communication(timestamptz,integer) FROM PUBLIC;

COMMENT ON TABLE public.resena_ensayo_local IS 'Synthetic local reviews; remove after 24 calendar months from creation. Not a legal retention determination.';
COMMENT ON TABLE public.reporte_resena_ensayo_local IS 'Synthetic local moderation report; retain while pending and 24 months after resolution. Not a legal retention determination.';
COMMENT ON TABLE public.aviso_local IS 'Durable local Mailpit notice intent. SMTP may duplicate after uncertain acceptance; no exactly-once guarantee.';

-- LOCAL-COMM-01 follow-up: retain anonymous review uniqueness and serialize
-- review/report/outbox operations with local account suppression.

DO $$
DECLARE c record;
BEGIN
  FOR c IN
    SELECT conname FROM pg_constraint
    WHERE conrelid='public.resena_ensayo_local'::regclass AND contype='c'
      AND pg_get_constraintdef(oid) LIKE '%destinatario_tipo%'
  LOOP
    EXECUTE format('ALTER TABLE public.resena_ensayo_local DROP CONSTRAINT %I', c.conname);
  END LOOP;
END $$;

ALTER TABLE public.resena_ensayo_local
  DROP CONSTRAINT IF EXISTS resena_destinatario_privacidad_ck,
  ADD CONSTRAINT resena_destinatario_privacidad_ck CHECK (
    (destinatario_tipo='espacio' AND destinatario_id IS NULL) OR
    (destinatario_tipo='arrendatario' AND destinatario_id IS NOT NULL) OR
    (destinatario_tipo='arrendatario_retirado' AND destinatario_id IS NULL)
  );
ALTER TABLE public.resena_ensayo_local
  ADD CONSTRAINT resena_destinatario_tipo_ck CHECK (destinatario_tipo IN ('espacio','arrendatario','arrendatario_retirado'));

-- Digest of reservation UUID + author UUID. It contains no review content or
-- directly identifying foreign key and is retained only as long as reservation
-- links can still authorize a new review.
CREATE TABLE public.resena_autoria_marca_local (
  huella_autoria bytea PRIMARY KEY CHECK (octet_length(huella_autoria)=32),
  creada_en timestamptz NOT NULL,
  retirar_en timestamptz
);
INSERT INTO public.resena_autoria_marca_local(huella_autoria,creada_en,retirar_en)
SELECT sha256(convert_to(r.reserva_id::text || ':' || r.autor_id::text,'UTF8')), r.creada_en,
       CASE WHEN b.vinculos_retirar_en IS NULL THEN NULL
            ELSE GREATEST(r.creada_en + interval '24 months',b.vinculos_retirar_en) END
FROM public.resena_ensayo_local r
JOIN public.reserva_ensayo_local b ON b.id=r.reserva_id
WHERE r.autor_id IS NOT NULL
ON CONFLICT DO NOTHING;

CREATE INDEX resena_autoria_marca_retencion_idx ON public.resena_autoria_marca_local(retirar_en,huella_autoria);

CREATE OR REPLACE FUNCTION public.purge_expired_local_communication(p_at timestamptz,p_limit integer)
RETURNS TABLE(reviews_purged bigint,reports_purged bigint,notices_purged bigint)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE ids uuid[];
BEGIN
  IF p_limit<1 OR p_limit>500 THEN RAISE EXCEPTION 'invalid batch'; END IF;
  SELECT array_agg(id) INTO ids FROM (
    SELECT r.id FROM public.reporte_resena_ensayo_local r
    WHERE r.estado IN ('desestimada','oculta') AND r.retirar_en<=p_at
    ORDER BY r.retirar_en,r.id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ) due;
  IF cardinality(ids)>0 THEN
    DELETE FROM public.reporte_resena_historial_local WHERE reporte_id=ANY(ids);
    DELETE FROM public.reporte_resena_ensayo_local WHERE id=ANY(ids);
    GET DIAGNOSTICS reports_purged = ROW_COUNT;
  ELSE reports_purged := 0; END IF;

  SELECT array_agg(id) INTO ids FROM (
    SELECT r.id FROM public.resena_ensayo_local r
    WHERE r.retirar_en<=p_at AND NOT EXISTS(SELECT 1 FROM public.reporte_resena_ensayo_local q WHERE q.resena_id=r.id)
    ORDER BY r.retirar_en,r.id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ) due;
  IF cardinality(ids)>0 THEN
    DELETE FROM public.resena_ensayo_local WHERE id=ANY(ids);
    GET DIAGNOSTICS reviews_purged = ROW_COUNT;
  ELSE reviews_purged := 0; END IF;

  SELECT array_agg(id) INTO ids FROM (
    SELECT a.id FROM public.aviso_local a
    WHERE a.retirar_en<=p_at AND a.estado IN ('entregada','fallo_terminal','cancelada') AND a.lease_hasta IS NULL
    ORDER BY a.retirar_en,a.id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ) due;
  IF cardinality(ids)>0 THEN
    DELETE FROM public.aviso_local_ciclo WHERE aviso_id=ANY(ids);
    DELETE FROM public.aviso_local WHERE id=ANY(ids);
    GET DIAGNOSTICS notices_purged = ROW_COUNT;
  ELSE notices_purged := 0; END IF;

  DELETE FROM public.resena_autoria_marca_local WHERE retirar_en<=p_at;
  DELETE FROM public.aviso_local_recuperacion_auditoria
  WHERE id IN (SELECT id FROM public.aviso_local_recuperacion_auditoria ORDER BY retirar_en,id LIMIT p_limit)
    AND retirar_en<=p_at;
  RETURN NEXT;
END $$;

COMMENT ON TABLE public.resena_autoria_marca_local IS 'Opaque uniqueness marker only; no rating/comment/account identifier. A NULL retirement date means the reservation still permits reviews; otherwise retained through the reservation-link deadline.';

-- LOCAL-DIS-01: record an administrative synthetic adjudication, separately
-- from every financial effect. LOCAL-FIN-01 owns any capture/release/settlement.
ALTER TABLE public.reclamo_dano_ensayo_local
  DROP CONSTRAINT reclamo_dano_ensayo_local_estado_check,
  ADD CONSTRAINT reclamo_dano_ensayo_local_estado_check CHECK (estado IN ('abierto','resuelta'));

CREATE TABLE public.reclamo_dano_resolucion_ensayo_local (
  reclamo_id uuid PRIMARY KEY REFERENCES public.reclamo_dano_ensayo_local(id) ON DELETE RESTRICT,
  resultado text NOT NULL CHECK (resultado IN ('acogido','rechazado')),
  motivo_codigo text NOT NULL CHECK (motivo_codigo IN ('evidencia_suficiente','evidencia_insuficiente','hecho_no_acreditado','informacion_insuficiente')),
  administrador_id uuid NOT NULL REFERENCES public.usuario(id) ON DELETE RESTRICT,
  resuelta_en timestamptz NOT NULL,
  clave_idempotencia text NOT NULL CHECK (length(btrim(clave_idempotencia)) BETWEEN 8 AND 200),
  huella_solicitud bytea NOT NULL CHECK (octet_length(huella_solicitud)=32),
  CHECK ((resultado='acogido' AND motivo_codigo='evidencia_suficiente') OR
         (resultado='rechazado' AND motivo_codigo<>'evidencia_suficiente')),
  UNIQUE(administrador_id,clave_idempotencia)
);

ALTER TABLE public.reclamo_dano_historial_ensayo_local
  DROP CONSTRAINT reclamo_dano_historial_ensayo_local_accion_check,
  ADD CONSTRAINT reclamo_dano_historial_ensayo_local_accion_check CHECK (accion IN ('reclamo_abierto','descargo_registrado','reclamo_resuelto'));

ALTER TABLE public.evento_auditoria_local DROP CONSTRAINT evento_auditoria_idempotencia_ck;
ALTER TABLE public.evento_auditoria_local ADD CONSTRAINT evento_auditoria_idempotencia_ck CHECK (
  clave_idempotencia IS NULL OR (
    length(btrim(clave_idempotencia)) BETWEEN 1 AND 200
    AND ((accion IN ('privacy.suppression.review','privacy.suppression.execute') AND recurso_tipo='solicitud_titular')
      OR (accion='identity.credential_notice.reopen' AND recurso_tipo='outbox_evento')
      OR (accion='reputation.review.moderate' AND recurso_tipo='reporte_resena')
      OR (accion='local.damage_claim.resolve' AND recurso_tipo='reclamo_dano'))
  )
);

ALTER TABLE public.aviso_local DROP CONSTRAINT aviso_local_tipo_evento_check,
  ADD CONSTRAINT aviso_local_tipo_evento_check CHECK (tipo_evento IN ('checkin_registrado','resena_reportada','reclamo_abierto','reclamo_resuelto','reserva_cancelada'));

CREATE FUNCTION public.enqueue_local_damage_claim_resolution_notice() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE claim public.reclamo_dano_ensayo_local%ROWTYPE;
BEGIN
  SELECT * INTO claim FROM public.reclamo_dano_ensayo_local WHERE id=NEW.reclamo_id;
  PERFORM public.enqueue_local_notice('reclamo_resuelto','reserva',claim.reserva_id,claim.anfitrion_id,
    'claim-resolved:'||claim.id::text||':'||claim.anfitrion_id::text,NEW.resuelta_en);
  PERFORM public.enqueue_local_notice('reclamo_resuelto','reserva',claim.reserva_id,claim.arrendatario_id,
    'claim-resolved:'||claim.id::text||':'||claim.arrendatario_id::text,NEW.resuelta_en);
  RETURN NEW;
END $$;
CREATE TRIGGER local_damage_claim_resolution_notice_trg
  AFTER INSERT ON public.reclamo_dano_resolucion_ensayo_local
  FOR EACH ROW EXECUTE FUNCTION public.enqueue_local_damage_claim_resolution_notice();

COMMENT ON TABLE public.reclamo_dano_resolucion_ensayo_local IS
  'Synthetic local adjudication only. It stores no guarantee amount and performs no capture, release, refund or settlement; those effects are deferred to LOCAL-FIN-01.';

-- Administrative local block is distinct from login throttling, KYC revocation,
-- and privacy suppression. Current state is separate from the account lifecycle.
CREATE TABLE public.bloqueo_cuenta_administrativo_local (
    cuenta_id uuid PRIMARY KEY REFERENCES public.usuario(id) ON DELETE RESTRICT,
    bloqueada_por uuid NOT NULL REFERENCES public.usuario(id) ON DELETE RESTRICT,
    motivo_codigo text NOT NULL CHECK (motivo_codigo IN ('riesgo_seguridad','uso_indebido','revision_administrativa')),
    bloqueada_en timestamptz NOT NULL,
    correlacion_id text NOT NULL CHECK (length(btrim(correlacion_id)) BETWEEN 1 AND 120)
);

CREATE TABLE public.bloqueo_cuenta_historial_local (
    id uuid PRIMARY KEY,
    cuenta_id uuid NOT NULL REFERENCES public.usuario(id) ON DELETE RESTRICT,
    actor_id uuid NOT NULL REFERENCES public.usuario(id) ON DELETE RESTRICT,
    accion text NOT NULL CHECK (accion IN ('bloquear','desbloquear')),
    motivo_codigo text NOT NULL CHECK (motivo_codigo IN ('riesgo_seguridad','uso_indebido','revision_administrativa','revision_concluida','error_bloqueo','riesgo_resuelto')),
    ocurrida_en timestamptz NOT NULL,
    correlacion_id text NOT NULL CHECK (length(btrim(correlacion_id)) BETWEEN 1 AND 120)
);
CREATE INDEX bloqueo_cuenta_historial_local_idx ON public.bloqueo_cuenta_historial_local(cuenta_id,ocurrida_en,id);

COMMENT ON TABLE public.bloqueo_cuenta_administrativo_local IS 'Bloqueo sintético separado de usuario.estado, KYC y baja; conserva reservas y obligaciones.';
COMMENT ON TABLE public.bloqueo_cuenta_historial_local IS 'Historial append-only de gobierno local de cuentas; auditoría de cinco años también queda en evento_auditoria_local.';

-- Administrative account-block state is removed when privacy suppression is
-- executed; its append-only history remains as a minimized technical record.
-- No retention deadline is assigned here because the user has not ratified one.
ALTER TABLE public.bloqueo_cuenta_historial_local
    ALTER COLUMN actor_id DROP NOT NULL;
ALTER TABLE public.bloqueo_cuenta_administrativo_local
    ALTER COLUMN bloqueada_por DROP NOT NULL;

COMMENT ON COLUMN public.bloqueo_cuenta_historial_local.actor_id IS
    'Nullable when the actor account is retired; privacy execution may remove the personal link while preserving the structured event.';
COMMENT ON COLUMN public.bloqueo_cuenta_administrativo_local.bloqueada_por IS
    'Nullable when the administrator actor is retired; the active block remains effective without retaining that personal link.';

-- LOCAL-CLOSE-01A: finite transactional local notice producers for the
-- ratified synthetic flows. Mailpit may duplicate delivery after uncertainty.
ALTER TABLE public.aviso_local DROP CONSTRAINT aviso_local_tipo_evento_check;
ALTER TABLE public.aviso_local ADD CONSTRAINT aviso_local_tipo_evento_check
  CHECK (tipo_evento IN (
    'checkin_registrado','resena_reportada','reclamo_abierto','reclamo_resuelto','reserva_cancelada',
    'cuenta_bloqueada_login','verificacion_aprobada','verificacion_rechazada','pago_arriendo_confirmado','pago_arriendo_rechazado',
    'nueva_reserva_pagada','invitacion_firma','contrato_firmado'
  ));
ALTER TABLE public.aviso_local DROP CONSTRAINT aviso_local_agregado_tipo_check;
ALTER TABLE public.aviso_local ADD CONSTRAINT aviso_local_agregado_tipo_check
  CHECK (agregado_tipo IN ('reserva','reporte_resena','usuario','verificacion','contrato'));

-- A fifth failed login updates bloqueado_hasta under the account transaction;
-- this trigger inserts only an event code/reference, never email or credentials.
CREATE FUNCTION public.enqueue_login_lock_notice() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.bloqueado_hasta IS NOT NULL AND NEW.bloqueado_hasta IS DISTINCT FROM OLD.bloqueado_hasta THEN
    PERFORM public.enqueue_local_notice(
      'cuenta_bloqueada_login','usuario',NEW.id,NEW.id,
      'login-lock:'||NEW.id::text||':'||extract(epoch FROM NEW.bloqueado_hasta)::text,
      COALESCE(NEW.actualizado_en,NEW.bloqueado_hasta));
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER local_login_lock_notice_trg AFTER UPDATE OF bloqueado_hasta ON public.usuario
  FOR EACH ROW EXECUTE FUNCTION public.enqueue_login_lock_notice();

CREATE FUNCTION public.enqueue_verification_result_notice() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.estado='en_revision' AND NEW.estado IN ('aprobada','rechazada') THEN
    PERFORM public.enqueue_local_notice('verificacion_'||NEW.estado,'verificacion',NEW.id,NEW.usuario_id,
      'verification-result:'||NEW.id::text||':'||NEW.estado,NEW.resuelta_en);
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER local_verification_result_notice_trg AFTER UPDATE OF estado ON public.verificacion
  FOR EACH ROW EXECUTE FUNCTION public.enqueue_verification_result_notice();

CREATE FUNCTION public.enqueue_booking_payment_notices() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.estado IS DISTINCT FROM NEW.estado AND NEW.estado='pagada' THEN
    PERFORM public.enqueue_local_notice('pago_arriendo_confirmado','reserva',NEW.id,NEW.arrendatario_id,
      'rental-payment:'||NEW.id::text||':confirmed',NEW.actualizada_en);
    PERFORM public.enqueue_local_notice('nueva_reserva_pagada','reserva',NEW.id,NEW.anfitrion_id,
      'paid-booking:'||NEW.id::text||':host',NEW.actualizada_en);
  ELSIF OLD.estado IS DISTINCT FROM NEW.estado AND NEW.estado='cancelada_por_pago' THEN
    -- Guarantee rejection/expiry also cancels a previously paid rental. Only
    -- emit RQF-201 when the rental payment operation itself was rejected.
    IF EXISTS (SELECT 1 FROM public.reserva_pago_ensayo p
      WHERE p.reserva_id=NEW.id AND p.resultado='rechazo_simulado') THEN
      PERFORM public.enqueue_local_notice('pago_arriendo_rechazado','reserva',NEW.id,NEW.arrendatario_id,
        'rental-payment:'||NEW.id::text||':rejected',NEW.actualizada_en);
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER local_booking_payment_notice_trg AFTER UPDATE OF estado ON public.reserva_ensayo_local
  FOR EACH ROW EXECUTE FUNCTION public.enqueue_booking_payment_notices();

-- Invitations identify a local resource only. The emailed link contains no
-- session token; the mock/API must authenticate and re-check participant ACL.
CREATE FUNCTION public.enqueue_contract_signature_notices() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE contract_row public.contrato_ensayo_local%ROWTYPE;
BEGIN
  SELECT * INTO contract_row FROM public.contrato_ensayo_local WHERE id=NEW.contrato_id;
  IF NEW.estado='pendiente' THEN
    PERFORM public.enqueue_local_notice('invitacion_firma','contrato',NEW.contrato_id,NEW.firmante_id,
      'contract-invite:'||NEW.contrato_id::text||':'||NEW.firmante_id::text,NEW.actualizada_en);
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER local_contract_signature_notice_trg AFTER INSERT ON public.contrato_ensayo_firma
  FOR EACH ROW EXECUTE FUNCTION public.enqueue_contract_signature_notices();

CREATE FUNCTION public.enqueue_contract_complete_notices() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE reservation_row public.reserva_ensayo_local%ROWTYPE;
BEGIN
  IF OLD.estado IS DISTINCT FROM NEW.estado AND NEW.estado='firmado' THEN
    SELECT * INTO reservation_row FROM public.reserva_ensayo_local WHERE id=NEW.reserva_id;
    PERFORM public.enqueue_local_notice('contrato_firmado','contrato',NEW.id,reservation_row.anfitrion_id,
      'contract-signed:'||NEW.id::text||':'||reservation_row.anfitrion_id::text,NEW.firmado_en);
    PERFORM public.enqueue_local_notice('contrato_firmado','contrato',NEW.id,reservation_row.arrendatario_id,
      'contract-signed:'||NEW.id::text||':'||reservation_row.arrendatario_id::text,NEW.firmado_en);
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER local_contract_complete_notice_trg AFTER UPDATE OF estado ON public.contrato_ensayo_local
  FOR EACH ROW EXECUTE FUNCTION public.enqueue_contract_complete_notices();

COMMENT ON FUNCTION public.enqueue_login_lock_notice() IS 'Durable synthetic login lockout notice. Never stores a password, token or email.';
COMMENT ON FUNCTION public.enqueue_contract_signature_notices() IS 'Authenticated-link invitation event; no bearer secret is placed in the URL.';

-- LOCAL-CLOSE-01B: execute already-ratified local retention deadlines.
-- The private blob is unlinked only after the durable job succeeds; KYC
-- metadata and history remain available until their independent two-year date.
ALTER TABLE public.verificacion_evidencia_sintetica
    ADD COLUMN archivo_id uuid,
    ADD COLUMN retirar_archivo_en timestamptz,
    ADD COLUMN archivo_retirado_en timestamptz;

UPDATE public.verificacion_evidencia_sintetica e
SET archivo_id=e.id,
    retirar_archivo_en=CASE
      WHEN v.estado='retirada_privacidad' THEN v.retirada_privacidad_en
      WHEN v.resuelta_en IS NOT NULL THEN v.resuelta_en + interval '90 days'
      ELSE NULL END
FROM public.verificacion v WHERE v.id=e.verificacion_id;

-- Existing evidence rows receive their storage reference and deadline before
-- the invariant is installed. Validate it explicitly so upgrades from V46 do
-- not fail while legacy rows are still being backfilled.
ALTER TABLE public.verificacion_evidencia_sintetica
    ADD CONSTRAINT verificacion_evidencia_archivo_retencion_ck CHECK (
        (archivo_id IS NULL AND archivo_retirado_en IS NOT NULL)
        OR (archivo_id IS NOT NULL AND archivo_retirado_en IS NULL)
    ) NOT VALID;
ALTER TABLE public.verificacion_evidencia_sintetica
    VALIDATE CONSTRAINT verificacion_evidencia_archivo_retencion_ck;

CREATE INDEX verificacion_evidencia_archivo_retencion_idx
    ON public.verificacion_evidencia_sintetica(retirar_archivo_en,id)
    WHERE archivo_id IS NOT NULL AND retirar_archivo_en IS NOT NULL;

CREATE TABLE public.verificacion_archivo_retiro_pendiente_local (
    evidencia_id uuid PRIMARY KEY,
    archivo_id uuid NOT NULL,
    disponible_en timestamptz NOT NULL,
    lease_hasta timestamptz,
    intentos integer NOT NULL DEFAULT 0 CHECK (intentos >= 0),
    ultimo_codigo_error text,
    CONSTRAINT verificacion_archivo_retiro_error_ck CHECK (
        ultimo_codigo_error IS NULL OR ultimo_codigo_error='archivo_sintetico_no_retirado'
    )
);
CREATE INDEX verificacion_archivo_retiro_claim_idx
    ON public.verificacion_archivo_retiro_pendiente_local(disponible_en,evidencia_id);

CREATE OR REPLACE FUNCTION public.set_verification_evidence_retention_deadline()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
  IF NEW.estado='retirada_privacidad' AND NEW.retirada_privacidad_en IS NOT NULL THEN
    UPDATE public.verificacion_evidencia_sintetica
       SET retirar_archivo_en=LEAST(COALESCE(retirar_archivo_en,NEW.retirada_privacidad_en),NEW.retirada_privacidad_en)
     WHERE verificacion_id=NEW.id AND archivo_id IS NOT NULL;
  ELSIF NEW.estado IN ('aprobada','rechazada','revocada') AND NEW.resuelta_en IS NOT NULL THEN
    UPDATE public.verificacion_evidencia_sintetica
       SET retirar_archivo_en=NEW.resuelta_en + interval '90 days'
     WHERE verificacion_id=NEW.id AND archivo_id IS NOT NULL;
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER verificacion_evidencia_retencion_trg
AFTER UPDATE OF estado,resuelta_en,retirada_privacidad_en ON public.verificacion
FOR EACH ROW EXECUTE FUNCTION public.set_verification_evidence_retention_deadline();

CREATE OR REPLACE FUNCTION public.purge_expired_local_privacy_rows(p_at timestamptz,p_limit integer)
RETURNS TABLE(terms_purged bigint,rights_purged bigint,quotes_purged bigint,verifications_purged bigint,files_queued bigint)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE ids uuid[]; owner_ids uuid[]; verification_ids uuid[];
BEGIN
  IF p_limit<1 OR p_limit>500 THEN RAISE EXCEPTION 'invalid batch'; END IF;
  terms_purged:=0; rights_purged:=0; quotes_purged:=0; verifications_purged:=0; files_queued:=0;

  INSERT INTO public.verificacion_archivo_retiro_pendiente_local(evidencia_id,archivo_id,disponible_en)
  SELECT e.id,e.archivo_id,p_at
    FROM public.verificacion_evidencia_sintetica e JOIN public.verificacion v ON v.id=e.verificacion_id
   WHERE e.archivo_id IS NOT NULL
     AND v.estado<>'retirada_privacidad'
     AND (e.retirar_archivo_en<=p_at OR v.retirar_en<=p_at)
     AND NOT EXISTS(SELECT 1 FROM public.verificacion_archivo_retiro_pendiente_local j WHERE j.evidencia_id=e.id)
   ORDER BY COALESCE(e.retirar_archivo_en,v.retirar_en),e.id
   LIMIT p_limit
  ON CONFLICT(evidencia_id) DO NOTHING;
  GET DIAGNOSTICS files_queued=ROW_COUNT;

  WITH due AS (
    SELECT id FROM public.aceptacion_terminos WHERE retirar_en<=p_at
    ORDER BY retirar_en,id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ) DELETE FROM public.aceptacion_terminos a USING due WHERE a.id=due.id;
  GET DIAGNOSTICS terms_purged=ROW_COUNT;

  -- A completed suppression's operation record shares its five-year period.
  -- Remove only completed filesystem jobs first; pending work has no deadline.
  SELECT array_agg(id) INTO ids FROM (
    SELECT id FROM public.ejecucion_baja_local WHERE retirar_en<=p_at
    ORDER BY retirar_en,id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ) due;
  IF cardinality(ids)>0 THEN
    DELETE FROM public.baja_archivo_pendiente_local WHERE ejecucion_id=ANY(ids) AND completada_en IS NOT NULL;
    DELETE FROM public.ejecucion_baja_local WHERE id=ANY(ids);
  END IF;
  WITH due AS (
    SELECT q.id FROM public.solicitud_titular q
    WHERE q.retirar_en<=p_at
      AND NOT EXISTS(SELECT 1 FROM public.ejecucion_baja_local x WHERE x.solicitud_id=q.id)
    ORDER BY q.retirar_en,q.id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ) DELETE FROM public.solicitud_titular q USING due WHERE q.id=due.id;
  GET DIAGNOSTICS rights_purged=ROW_COUNT;

  WITH due AS (
    SELECT q.id FROM public.cotizacion_reserva_ensayo q
    WHERE q.retirar_en<=p_at
      AND NOT EXISTS(SELECT 1 FROM public.reserva_ensayo_local r WHERE r.cotizacion_id=q.id)
    ORDER BY q.retirar_en,q.id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ) DELETE FROM public.cotizacion_reserva_ensayo q USING due WHERE q.id=due.id;
  GET DIAGNOSTICS quotes_purged=ROW_COUNT;

  -- Follow the account -> verification lock order used by verification and
  -- suppression writers. SKIP LOCKED makes concurrent passes retryable.
  SELECT array_agg(id) INTO owner_ids FROM (
    SELECT u.id FROM public.usuario u
    WHERE EXISTS(SELECT 1 FROM public.verificacion v WHERE v.usuario_id=u.id
      AND v.retirar_en<=p_at AND v.estado IN ('aprobada','rechazada','revocada','retirada_privacidad'))
    ORDER BY u.id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ) owners;
  IF cardinality(owner_ids)>0 THEN
    SELECT array_agg(id) INTO verification_ids FROM (
      SELECT v.id FROM public.verificacion v
      WHERE v.usuario_id=ANY(owner_ids) AND v.retirar_en<=p_at
        AND v.estado IN ('aprobada','rechazada','revocada','retirada_privacidad')
        AND NOT EXISTS(SELECT 1 FROM public.verificacion_evidencia_sintetica e
                       WHERE e.verificacion_id=v.id AND e.archivo_id IS NOT NULL)
        AND NOT EXISTS(SELECT 1 FROM public.ejecucion_baja_local b
                       WHERE b.usuario_id=v.usuario_id AND b.estado='limpieza_pendiente')
      ORDER BY v.usuario_id,v.retirar_en,v.id FOR UPDATE SKIP LOCKED LIMIT p_limit
    ) due_verifications;
  END IF;
  IF cardinality(verification_ids)>0 THEN
    UPDATE public.verificacion SET reintento_de=NULL WHERE reintento_de=ANY(verification_ids);
    DELETE FROM public.elegibilidad_verificacion_local WHERE verificacion_id=ANY(verification_ids);
    DELETE FROM public.verificacion_historial_local WHERE verificacion_id=ANY(verification_ids);
    DELETE FROM public.verificacion_evidencia_sintetica WHERE verificacion_id=ANY(verification_ids);
    DELETE FROM public.verificacion WHERE id=ANY(verification_ids);
    GET DIAGNOSTICS verifications_purged=ROW_COUNT;
  END IF;
  RETURN NEXT;
END;
$$;

CREATE OR REPLACE FUNCTION public.claim_expired_local_verification_files(p_at timestamptz,p_limit integer)
RETURNS TABLE(evidencia_id uuid,archivo_id uuid)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
  IF p_limit<1 OR p_limit>500 THEN RAISE EXCEPTION 'invalid batch'; END IF;
  RETURN QUERY
  WITH due AS (
    SELECT j.evidencia_id FROM public.verificacion_archivo_retiro_pendiente_local j
    WHERE j.disponible_en<=p_at AND (j.lease_hasta IS NULL OR j.lease_hasta<=p_at)
    ORDER BY j.disponible_en,j.evidencia_id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ), claimed AS (
    UPDATE public.verificacion_archivo_retiro_pendiente_local j
       SET lease_hasta=p_at+interval '5 minutes',intentos=intentos+1
      FROM due WHERE j.evidencia_id=due.evidencia_id
    RETURNING j.evidencia_id,j.archivo_id
  ) SELECT claimed.evidencia_id,claimed.archivo_id FROM claimed;
END;
$$;

CREATE OR REPLACE FUNCTION public.complete_expired_local_verification_file(p_evidencia uuid,p_at timestamptz)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE file_id uuid;
BEGIN
  SELECT archivo_id INTO file_id FROM public.verificacion_archivo_retiro_pendiente_local
   WHERE evidencia_id=p_evidencia FOR UPDATE;
  IF file_id IS NULL THEN RETURN false; END IF;
  UPDATE public.verificacion_evidencia_sintetica
     SET archivo_id=NULL,archivo_retirado_en=p_at
   WHERE id=p_evidencia AND archivo_id=file_id;
  DELETE FROM public.verificacion_archivo_retiro_pendiente_local WHERE evidencia_id=p_evidencia;
  RETURN true;
END;
$$;

CREATE OR REPLACE FUNCTION public.fail_expired_local_verification_file(p_evidencia uuid,p_at timestamptz)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
  UPDATE public.verificacion_archivo_retiro_pendiente_local
     SET intentos=intentos+0,lease_hasta=NULL,
         disponible_en=p_at+LEAST(interval '1 hour',interval '5 seconds' * (1 << LEAST(intentos,9))),
         ultimo_codigo_error='archivo_sintetico_no_retirado'
   WHERE evidencia_id=p_evidencia;
  RETURN FOUND;
END;
$$;

REVOKE ALL ON FUNCTION public.purge_expired_local_privacy_rows(timestamptz,integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.claim_expired_local_verification_files(timestamptz,integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.complete_expired_local_verification_file(uuid,timestamptz) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fail_expired_local_verification_file(uuid,timestamptz) FROM PUBLIC;
REVOKE ALL ON TABLE public.verificacion_archivo_retiro_pendiente_local FROM PUBLIC;
COMMENT ON TABLE public.verificacion_archivo_retiro_pendiente_local IS 'Durable, retryable deletion of local synthetic verification blobs; contains no user or provider payload.';

-- LOCAL-M10-BOOKING-CLOSE-01. A successful, persisted fake settlement may
-- close a finalized reservation. No snapshot, amount or historical row is
-- rewritten by this state extension.
ALTER TABLE public.reserva_ensayo_local
    DROP CONSTRAINT reserva_ensayo_local_estado_check,
    ADD CONSTRAINT reserva_ensayo_local_estado_check CHECK (estado IN (
        'pendiente_de_pago','pagada','aprobada_host','firma_parcial','lista_para_checkin',
        'en_curso','finalizada','en_disputa','cerrada','cancelada_por_pago','rechazada_arrendador',
        'vencida_pago','vencida_host','cancelada_arrendatario','cancelada_por_firma'
    ));

-- Keep the terminal transition tied to the persisted result in the same
-- transaction. A handler-only guard would allow a runtime writer to close a
-- reservation before the fake settlement had actually been applied.
CREATE OR REPLACE FUNCTION public.guard_local_reservation_close_after_settlement() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF OLD.estado IS DISTINCT FROM 'cerrada' AND NEW.estado='cerrada' THEN
        IF OLD.estado IS DISTINCT FROM 'finalizada' OR NOT EXISTS (
            SELECT 1
            FROM public.reserva_liquidacion_ensayo_local s
            JOIN public.reserva_liquidacion_operacion_ensayo_local o ON o.liquidacion_id=s.id
            JOIN public.reserva_liquidacion_resultado_fake_ensayo_local f ON f.operacion_id=o.id
            WHERE s.reserva_id=NEW.id
              AND s.estado='liquidada'
              AND s.ultimo_resultado='exito_simulado'
              AND f.resultado='exito_simulado'
        ) THEN
            RAISE EXCEPTION 'only a finalized reservation with a confirmed fake settlement can be closed'
                USING ERRCODE='23514', CONSTRAINT='reserva_cerrada_liquidacion_fake_ck';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS reserva_cerrada_liquidacion_fake_guard ON public.reserva_ensayo_local;
CREATE TRIGGER reserva_cerrada_liquidacion_fake_guard
BEFORE UPDATE OF estado ON public.reserva_ensayo_local
FOR EACH ROW EXECUTE FUNCTION public.guard_local_reservation_close_after_settlement();

-- Closing is a terminal booking state and starts the already-ratified link
-- retention period from the actual close transition; no shared retention is
-- added to unrelated tables.
CREATE OR REPLACE FUNCTION public.schedule_local_reservation_link_retention() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.estado IN ('finalizada','cerrada','cancelada_por_pago','rechazada_arrendador','vencida_pago','vencida_host','cancelada_arrendatario')
       AND (TG_OP='INSERT' OR OLD.estado IS DISTINCT FROM NEW.estado) THEN
        NEW.vinculos_retirar_en := GREATEST(COALESCE(NEW.vinculos_retirar_en,'epoch'::timestamptz),NEW.actualizada_en + interval '24 months');
    END IF;
    RETURN NEW;
END;
$$;

DROP INDEX IF EXISTS public.reserva_ensayo_retencion_local_idx;
CREATE INDEX reserva_ensayo_retencion_local_idx ON public.reserva_ensayo_local(vinculos_retirar_en,id)
WHERE estado IN ('finalizada','cerrada','cancelada_por_pago','rechazada_arrendador','vencida_pago','vencida_host','cancelada_arrendatario');

-- Keep immutable rate rows non-deletable for the runtime role. Publication
-- retirement may remove only unreferenced rates after the owning space has
-- been tombstoned; referenced snapshots remain protected by their FK.
CREATE OR REPLACE FUNCTION public.purge_unreferenced_local_publication_rates(p_space_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    removed_count integer;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.espacio
        WHERE id = p_space_id AND estado = 'eliminada'
    ) THEN
        RAISE EXCEPTION 'publication must be retired before rate cleanup'
            USING ERRCODE = '42501';
    END IF;

    DELETE FROM public.tarifa_espacio AS rate
    WHERE rate.espacio_id = p_space_id
      AND NOT EXISTS (
          SELECT 1 FROM public.cotizacion_reserva_ensayo AS quote
          WHERE quote.espacio_id = rate.espacio_id
            AND quote.tarifa_version = rate.version
      );
    GET DIAGNOSTICS removed_count = ROW_COUNT;
    RETURN removed_count;
END;
$$;

